def test_issue_8886():
    from sympy.physics.mechanics import ReferenceFrame as R
    from sympy.abc import x
    # if something can't be sympified we assume that it
    # doesn't play well with SymPy and disallow the
    # substitution
    v = R('A').x
    assert x.subs(x, v) == x
    assert v.subs(v, x) == v
    assert v.__eq__(x) is False


